import{_ as p,a0 as l,w as d,s as r,I as a,x as n,a1 as i,A as t,ao as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"在 KVM 中测试 IPv6 网络：第 2 部分 | LCTT x X-CMD","titleTemplate":false,"description":"在 KVM 中测试 IPv6 网络：第 2 部分 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 KVM 中测试 IPv6 网络：第 2 部分 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 KVM 中测试 IPv6 网络：第 2 部分 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20171109 Testing IPv6 Networking in KVM- Part 2","title":"在 KVM 中测试 IPv6 网络：第 2 部分","tag":"201805","desc":""},"relativePath":"201805/20171109 Testing IPv6 Networking in KVM- Part 2.md","filePath":"[post].md"}'),f={name:"201805/20171109 Testing IPv6 Networking in KVM- Part 2.md"};function m(u,s,g,b,k,c){const e=l("Link");return d(),r("div",null,[s[26]||(s[26]=a("h1",{id:"在-kvm-中测试-ipv6-网络-第-2-部分",tabindex:"-1"},[n("在 KVM 中测试 IPv6 网络：第 2 部分 "),a("a",{class:"header-anchor",href:"#在-kvm-中测试-ipv6-网络-第-2-部分","aria-label":"Permalink to “在 KVM 中测试 IPv6 网络：第 2 部分”"},"​")],-1)),s[27]||(s[27]=a("p",null,[a("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/banner_4.png?itok=yZBHylwd",alt:""})],-1)),a("p",null,[s[1]||(s[1]=n("我们又见面了，在上一篇 ",-1)),i(e,{href:"https://linux.cn/article-9594-1.html"},{default:t(()=>[...s[0]||(s[0]=[n("在 KVM 中测试 IPv6 网络：第 1 部分",-1)])]),_:1}),s[2]||(s[2]=n(" 中，我们学习了有关 IPv6 私有地址的内容。今天，我们将使用 KVM 创建一个网络，去测试上一星期学习的 IPv6 的内容。",-1))]),a("p",null,[s[5]||(s[5]=n("如果你想重新温习如何使用 KVM，可以查看 ",-1)),i(e,{href:"https://www.linux.com/learn/intro-to-linux/2017/5/creating-virtual-machines-kvm-part-1"},{default:t(()=>[...s[3]||(s[3]=[n("在 KVM 中创建虚拟机：第 1 部分",-1)])]),_:1}),s[6]||(s[6]=n(" 和 ",-1)),i(e,{href:"https://www.linux.com/learn/intro-to-linux/2017/5/creating-virtual-machines-kvm-part-2-networking"},{default:t(()=>[...s[4]||(s[4]=[n("在 KVM 中创建虚拟机：第 2 部分— 网络",-1)])]),_:1}),s[7]||(s[7]=n("。",-1))]),s[28]||(s[28]=a("h3",{id:"在-kvm-中创建网络",tabindex:"-1"},[n("在 KVM 中创建网络 "),a("a",{class:"header-anchor",href:"#在-kvm-中创建网络","aria-label":"Permalink to “在 KVM 中创建网络”"},"​")],-1)),s[29]||(s[29]=a("p",null,"在 KVM 中你至少需要两个虚拟机。当然了，如果你愿意，也可以创建更多的虚拟机。在我的系统中有 Fedora、Ubuntu、以及 openSUSE。去创建一个新的 IPv6 网络，在主虚拟机管理窗口中打开 “Edit > Connection Details > Virtual Networks”。点击左下角的绿色十字按钮去创建一个新的网络（图 1）。",-1)),s[30]||(s[30]=a("p",null,[a("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/kvm-fig-1_0.png?itok=ruqjPXxd",alt:""})],-1)),s[31]||(s[31]=a("p",null,[a("em",null,"图 1：创建一个网络")],-1)),s[32]||(s[32]=a("p",null,"给新网络输入一个名字，然后，点击 “Forward” 按钮。如果你愿意，也可以不创建 IPv4 网络。当你创建一个新的 IPv4 网络时，虚拟机管理器将不让你创建重复网络，或者是使用了一个无效地址。在我的宿主机 Ubuntu 系统上，有效的地址是以绿色高亮显示的，而无效地址是使用高亮的玫瑰红色调。在我的 openSUSE 机器上没有高亮颜色。启用或不启用 DHCP，以及创建或不创建一个静态路由，然后进入下一个窗口。",-1)),a("p",null,[s[9]||(s[9]=n("选中 “Enable IPv6 network address space definition”，然后输入你的私有地址范围。你可以使用任何你希望的 IPv6 地址类，但是要注意，不能将你的实验网络泄漏到公网上去。我们将使用非常好用的 IPv6 唯一本地地址（ULA），并且使用在 ",-1)),i(e,{href:"http://simpledns.com/private-ipv6.aspx"},{default:t(()=>[...s[8]||(s[8]=[n("Simple DNS Plus",-1)])]),_:1}),s[10]||(s[10]=n(" 上的在线地址生成器，去创建我们的网络地址。拷贝 “Combined/CID” 地址到网络框中（图 2）。",-1))]),s[33]||(s[33]=o(`<p><img src="https://www.linux.com/sites/lcom/files/styles/floated_images/public/kvm-fig-2.png?itok=gncdPGj-" alt="network address" title="network address"></p><p><em>图 2：拷贝 &quot;Combined/CID&quot; 地址到网络框中</em></p><p>虚拟机认为我的地址是无效的，因为，它显示了高亮的玫瑰红色。它做的对吗？我们使用 <code>ipv6calc</code> 去验证一下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ipv6calc -qi fd7d:844d:3e17:f3ae::/64</span></span>
<span class="line"><span>Address type: unicast, unique-local-unicast, iid, iid-local</span></span>
<span class="line"><span>Registry for address: reserved(RFC4193#3.1)</span></span>
<span class="line"><span>Address type has SLA: f3ae</span></span>
<span class="line"><span>Interface identifier: 0000:0000:0000:0000</span></span>
<span class="line"><span>Interface identifier is probably manual set</span></span></code></pre></div><p><code>ipv6calc</code> 认为没有问题。如果感兴趣，你可以改变其中一个数字为无效的东西，比如字母 <code>g</code>，然后再试一次。（问 “如果…？”，试验和错误是最好的学习方法）。</p><p>我们继续进行，启用 DHCPv6（图 3）。你可以接受缺省值，或者输入一个你自己的设置值。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/floated_images/public/kvm-fig-3.png?itok=F-oAAtN9" alt=""></p><p><em>图 3： 启用 DHCPv6</em></p><p>我们将跳过缺省路由定义这一步，继续进入下一屏，在那里我们将启用 “Isolated Virtual Network” 和 “Enable IPv6 internal routing/networking”。</p><h3 id="虚拟机网络选择" tabindex="-1">虚拟机网络选择 <a class="header-anchor" href="#虚拟机网络选择" aria-label="Permalink to “虚拟机网络选择”">​</a></h3><p>现在，你可以配置你的虚拟机去使用新的网络。打开你的虚拟机，然后点击顶部左侧的 “i” 按钮去打开 “Show virtual hardware details” 屏幕。在 “Add Hardware” 列点击 “NIC” 按钮去打开网络选择器，然后选择你喜欢的新的 IPv6 网络。点击 “Apply”，然后重新启动。（或者使用你喜欢的方法去重新启动网络，或者更新你的 DHCP 租期。）</p><h3 id="测试" tabindex="-1">测试 <a class="header-anchor" href="#测试" aria-label="Permalink to “测试”">​</a></h3><p><code>ifconfig</code> 告诉我们它做了什么？</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ifconfig</span></span>
<span class="line"><span>ens3: flags=4163 UP,BROADCAST,RUNNING,MULTICAST  mtu 1500</span></span>
<span class="line"><span> inet 192.168.30.207  netmask 255.255.255.0  </span></span>
<span class="line"><span>   broadcast 192.168.30.255</span></span>
<span class="line"><span> inet6 fd7d:844d:3e17:f3ae::6314  </span></span>
<span class="line"><span>   prefixlen 128  scopeid 0x0</span></span>
<span class="line"><span> inet6 fe80::4821:5ecb:e4b4:d5fc  </span></span>
<span class="line"><span>   prefixlen 64  scopeid 0x20</span></span></code></pre></div><p>这是我们新的 ULA，<code>fd7d:844d:3e17:f3ae::6314</code>，它是自动生成的本地链路地址。如果你有兴趣，可以 ping 一下，ping 网络上的其它虚拟机：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vm1 ~$ ping6 -c2 fd7d:844d:3e17:f3ae::2c9f</span></span>
<span class="line"><span>PING fd7d:844d:3e17:f3ae::2c9f(fd7d:844d:3e17:f3ae::2c9f) 56 data bytes</span></span>
<span class="line"><span>64 bytes from fd7d:844d:3e17:f3ae::2c9f: icmp_seq=1 ttl=64 time=0.635 ms</span></span>
<span class="line"><span>64 bytes from fd7d:844d:3e17:f3ae::2c9f: icmp_seq=2 ttl=64 time=0.365 ms</span></span>
<span class="line"><span></span></span>
<span class="line"><span>vm2 ~$ ping6 -c2 fd7d:844d:3e17:f3ae:a:b:c:6314</span></span>
<span class="line"><span>PING fd7d:844d:3e17:f3ae:a:b:c:6314(fd7d:844d:3e17:f3ae:a:b:c:6314) 56 data bytes</span></span>
<span class="line"><span>64 bytes from fd7d:844d:3e17:f3ae:a:b:c:6314: icmp_seq=1 ttl=64 time=0.744 ms</span></span>
<span class="line"><span>64 bytes from fd7d:844d:3e17:f3ae:a:b:c:6314: icmp_seq=2 ttl=64 time=0.364 ms</span></span></code></pre></div><p>当你努力去理解子网时，这是一个可以让你尝试不同地址是否可以正常工作的快速易用的方法。你可以给单个接口分配多个 IP 地址，然后 ping 它们去看一下会发生什么。在一个 ULA 中，接口，或者主机是 IP 地址的最后四部分，因此，你可以在那里做任何事情，只要它们在同一个子网中即可，在那个例子中是 <code>f3ae</code>。在我的其中一个虚拟机上，我只改变了这个示例的接口 ID，以展示使用这四个部分，你可以做任何你想做的事情：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vm1 ~$ sudo /sbin/ip -6 addr add fd7d:844d:3e17:f3ae:a:b:c:6314 dev ens3</span></span>
<span class="line"><span></span></span>
<span class="line"><span>vm2 ~$ ping6 -c2 fd7d:844d:3e17:f3ae:a:b:c:6314</span></span>
<span class="line"><span>PING fd7d:844d:3e17:f3ae:a:b:c:6314(fd7d:844d:3e17:f3ae:a:b:c:6314) 56 data bytes</span></span>
<span class="line"><span>64 bytes from fd7d:844d:3e17:f3ae:a:b:c:6314: icmp_seq=1 ttl=64 time=0.744 ms</span></span>
<span class="line"><span>64 bytes from fd7d:844d:3e17:f3ae:a:b:c:6314: icmp_seq=2 ttl=64 time=0.364 ms</span></span></code></pre></div><p>现在，尝试使用不同的子网，在下面的示例中使用了 <code>f4ae</code> 代替 <code>f3ae</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping6 -c2 fd7d:844d:3e17:f4ae:a:b:c:6314</span></span>
<span class="line"><span>PING fd7d:844d:3e17:f4ae:a:b:c:6314(fd7d:844d:3e17:f4ae:a:b:c:6314) 56 data bytes</span></span>
<span class="line"><span>From fd7d:844d:3e17:f3ae::1 icmp_seq=1 Destination unreachable: No route</span></span>
<span class="line"><span>From fd7d:844d:3e17:f3ae::1 icmp_seq=2 Destination unreachable: No route</span></span></code></pre></div><p>这也是练习路由的好机会，以后，我们将专门做一期，如何在不使用 DHCP 情况下实现自动寻址。</p><hr>`,22)),a("p",null,[s[12]||(s[12]=n("via: ",-1)),i(e,{href:"https://www.linux.com/learn/intro-to-linux/2017/11/testing-ipv6-networking-kvm-part-2"},{default:t(()=>[...s[11]||(s[11]=[n("https://www.linux.com/learn/intro-to-linux/2017/11/testing-ipv6-networking-kvm-part-2",-1)])]),_:1})]),a("p",null,[s[17]||(s[17]=n("作者：",-1)),i(e,{href:"https://www.linux.com/users/cschroder"},{default:t(()=>[...s[13]||(s[13]=[n("CARLA SCHRODER",-1)])]),_:1}),s[18]||(s[18]=n(" 选题：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[14]||(s[14]=[n("lujun9972",-1)])]),_:1}),s[19]||(s[19]=n(" 译者：",-1)),i(e,{href:"https://github.com/qhwdw"},{default:t(()=>[...s[15]||(s[15]=[n("qhwdw",-1)])]),_:1}),s[20]||(s[20]=n(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[16]||(s[16]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[23]||(s[23]=n("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[21]||(s[21]=[n("LCTT",-1)])]),_:1}),s[24]||(s[24]=n(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:t(()=>[...s[22]||(s[22]=[n("Linux中国",-1)])]),_:1}),s[25]||(s[25]=n(" 荣誉推出",-1))])])}const P=p(f,[["render",m]]);export{w as __pageData,P as default};
